import{_ as l,o as d,c as r,a2 as a,j as e,a as o}from"./chunks/framework.D0_YsCyK.js";const m=JSON.parse('{"title":"U2 审计：面板在线升级前端与接口契约","description":"","frontmatter":{},"headers":[],"relativePath":"audit/U2-panel-upgrade-frontend.md","filePath":"audit/U2-panel-upgrade-frontend.md","lastUpdated":1792473847000}'),n={name:"audit/U2-panel-upgrade-frontend.md"};function s(i,t,c,u,g,p){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="u2-审计-面板在线升级前端与接口契约" tabindex="-1">U2 审计：面板在线升级前端与接口契约 <a class="header-anchor" href="#u2-审计-面板在线升级前端与接口契约" aria-label="Permalink to &quot;U2 审计：面板在线升级前端与接口契约&quot;">​</a></h1><p>审计员：U2 ｜ 日期：2026-10-20 CST ｜ 基线：main（1.0.10 已发布后）｜ 方法：代码审查 + 前后端对表 + <code>npx tsc --noEmit</code>（只读，未改代码）</p><h2 id="结论速览" tabindex="-1">结论速览 <a class="header-anchor" href="#结论速览" aria-label="Permalink to &quot;结论速览&quot;">​</a></h2><ul><li><strong>P0 0 / P1 0 / P2 3 / P3 5</strong></li><li>面板自升级主链路（配置页：加载状态 → 检查更新 → 选版本 → 确认 → 后端执行）在契约层面<strong>通顺</strong>：三个接口路径/方法/字段与后端逐一对表通过，代理配置被检查与下载两条路径正确消费，用户填的 <code>https://ghfast.top</code> 归一化后可直接生效。</li><li>会卡住/误导用户的点不在主链路，而在三处外围：① WebView 下左下角版本是硬编码 &quot;1.0.0&quot;（更新红标常亮）；② 代理开关 UI 与后端默认值不一致（未保存过时 UI 显示&quot;已禁用&quot;、后端实际默认开启并用默认镜像）；③ 全站错误 Toast 只停留 2 秒且长字符串不换行——<strong>这正是用户刚才看不到完整升级报错的直接原因</strong>（面板自升级报错走同一 Toast）。</li></ul><hr><h2 id="p2-1-webview-下当前版本硬编码-1-0-0-更新红标常亮" tabindex="-1">P2-1 WebView 下当前版本硬编码 &quot;1.0.0&quot;，更新红标常亮 <a class="header-anchor" href="#p2-1-webview-下当前版本硬编码-1-0-0-更新红标常亮" aria-label="Permalink to &quot;P2-1 WebView 下当前版本硬编码 &quot;1.0.0&quot;，更新红标常亮&quot;">​</a></h2><ul><li><strong>证据</strong>： <ul><li><code>vite-frontend/src/config/site.ts:9</code>：<code>const APP_VERSION = &quot;1.0.0&quot;;</code>（硬编码，与实际版本 1.0.10 脱节，无任何机制随发版更新）</li><li><code>vite-frontend/src/pages/index.tsx:303</code> 与 <code>src/pages/profile.tsx:337</code>：页脚版本取值 <code>isWebView ? siteConfig.app_version : siteConfig.version</code><ul><li>普通浏览器走 <code>siteConfig.version</code> = <code>import.meta.env.VITE_APP_VERSION</code>，发版流水线在 <code>.github/workflows/docker-build.yml:182</code> 注入真实版本，<strong>正确</strong></li><li>WebView（App 内嵌）走 <code>siteConfig.app_version</code> = 硬编码 &quot;1.0.0&quot;，<strong>永远错误</strong></li></ul></li><li><code>vite-frontend/src/components/version-footer.tsx:74</code>：<code>hasVersionUpdate(version, latestVersion)</code> 用该错误版本比对 → App 内左下角恒显示&quot;有新版本&quot;红标（与用户 05:09 投诉的红标问题同类，当时只处理了 GitHub 残留 release 这一半，代码层面的另一半在此）</li></ul></li><li><strong>影响</strong>：仅 WebView 场景；普通浏览器不受影响。分级 P2（持续误导，无功能损害）。</li></ul><h2 id="p2-2-代理开关-ui-状态与后端默认值不一致-未保存过的安装" tabindex="-1">P2-2 代理开关 UI 状态与后端默认值不一致（未保存过的安装） <a class="header-anchor" href="#p2-2-代理开关-ui-状态与后端默认值不一致-未保存过的安装" aria-label="Permalink to &quot;P2-2 代理开关 UI 状态与后端默认值不一致（未保存过的安装）&quot;">​</a></h2><ul><li><strong>证据</strong>： <ul><li>后端 <code>go-backend/internal/http/handler/upgrade.go:37-38</code>：<code>defaultGithubProxyEnabled = true</code>、<code>defaultGithubProxyURL = &quot;https://gcode.hostcentral.cc&quot;</code></li><li>后端 <code>upgrade.go:89-108</code>（getGithubProxyConfig）：DB 无 <code>github_proxy_enabled</code> 行时保持默认 <strong>enabled=true</strong>；判断为 <code>enabledCfg.Value != &quot;false&quot;</code>（只有字面 &quot;false&quot; 才关）</li><li>前端 <code>vite-frontend/src/pages/config.tsx:1193</code>：开关 <code>isSelected={configs[item.key] === &quot;true&quot;}</code>，DB 无该行时 <code>configs</code> 里没有这个键 → 开关显示<strong>已禁用</strong></li></ul></li><li><strong>影响</strong>：从未保存过代理设置的面板，UI 显示&quot;加速已禁用&quot;，实际后端在用默认镜像 gcode.hostcentral.cc 下载（节点安装命令、内核、面板升级、节点升级下发全受影响）。管理员对&quot;流量到底走没走第三方镜像&quot;的认知与实际相反。<strong>本用户已显式保存 ghfast.top，不受此条影响</strong>（保存后行存在，UI 与后端一致）。分级 P2。</li></ul><h2 id="p2-3-错误-toast-2-秒消失-长字符串不换行-升级报错看不全-用户实测复现" tabindex="-1">P2-3 错误 Toast 2 秒消失 + 长字符串不换行，升级报错看不全（用户实测复现） <a class="header-anchor" href="#p2-3-错误-toast-2-秒消失-长字符串不换行-升级报错看不全-用户实测复现" aria-label="Permalink to &quot;P2-3 错误 Toast 2 秒消失 + 长字符串不换行，升级报错看不全（用户实测复现）&quot;">​</a></h2><ul><li><strong>证据</strong>： <ul><li><code>vite-frontend/src/provider.tsx:21-44</code>：全局 Toaster 配置，<code>error: { duration: 2000 }</code>（所有错误提示统一 2 秒），且未给 toast 内容设置 <code>maxWidth</code>/<code>wordBreak</code>，react-hot-toast 默认样式对无空格长串（URL）不折行，内容横向溢出视口被截断</li><li>面板自升级失败同样走此通道：<code>vite-frontend/src/pages/config.tsx</code> handleConfirmSystemUpgrade 的 <code>toast.error(response.msg || &quot;面板升级失败&quot;)</code>；检查更新失败 handleCheckSystemUpgrade 的 <code>toast.error(...)</code> 同理</li><li>节点升级报错链（用户截图）已核实完整送达前端：后端 <code>upgrade.go:233</code> SendCommand 拿到 agent 错误后以 <code>升级失败: %v</code> 返回，<code>vite-frontend/src/pages/node.tsx:1136</code> <code>toast.error(res.msg)</code> 呈现——<strong>数据没丢，是呈现层截断 + 2 秒消失</strong></li></ul></li><li><strong>影响</strong>：所有带长 URL/长堆栈的失败都不可诊断，用户只能截图到一半。分级 P2（可诊断性）。</li><li>修复方向（仅建议）：error toast 时长提高（如 8-10s）并加 <code>word-break: break-all; max-width: 90vw</code>；或升级类错误改在弹窗内/卡片内联展示并提供复制。</li></ul><h2 id="p3-1-升级确认框不回显-将升级到哪个版本-无更新时也可确认-同版本重装" tabindex="-1">P3-1 升级确认框不回显&quot;将升级到哪个版本&quot;，无更新时也可确认（同版本重装） <a class="header-anchor" href="#p3-1-升级确认框不回显-将升级到哪个版本-无更新时也可确认-同版本重装" aria-label="Permalink to &quot;P3-1 升级确认框不回显&quot;将升级到哪个版本&quot;，无更新时也可确认（同版本重装）&quot;">​</a></h2><ul><li><code>vite-frontend/src/pages/config.tsx:1945-2018</code>：确认弹窗只有注意事项与降级警告（O9-006 在 :1966-1985，复核<strong>有效</strong>：选中低版本时红框警告出现），未回显目标版本；版本留空时不显示&quot;将升级到最新版 X&quot;</li><li>&quot;立即升级&quot;按钮启用条件 <code>canTriggerSystemUpgrade</code>（:368-372）不要求 hasUpdate；后端 <code>system_upgrade.go</code> 对目标==当前（cmp==0）仅打日志、照常执行全量升级。结果是无更新时点确认会白跑一次同版本重装（备份/换 compose/重启俱全）。分级 P3。</li></ul><h2 id="p3-2-升级进行中状态不持久-刷新后无迹可寻" tabindex="-1">P3-2 升级进行中状态不持久，刷新后无迹可寻 <a class="header-anchor" href="#p3-2-升级进行中状态不持久-刷新后无迹可寻" aria-label="Permalink to &quot;P3-2 升级进行中状态不持久，刷新后无迹可寻&quot;">​</a></h2><ul><li>前端执行态仅 React state（<code>system_upgrade.go</code> 后端有 TryLock 防并发，冲突文案&quot;已有面板升级任务执行中&quot;）；升级触发后页面刷新/重启期间用户无从得知进度，只能等约 1 分钟手动刷新（成功 Toast 文案即如此引导）。后端进程在升级中会被 helper 替换，锁随进程消失；重启后再点一次升级会走同版本重装路径（见 P3-1），不会造成版本错乱。分级 P3（体验）。</li></ul><h2 id="p3-3-页脚更新检测由浏览器直连-api-github-com-与后端代理路径不一致" tabindex="-1">P3-3 页脚更新检测由浏览器直连 api.github.com，与后端代理路径不一致 <a class="header-anchor" href="#p3-3-页脚更新检测由浏览器直连-api-github-com-与后端代理路径不一致" aria-label="Permalink to &quot;P3-3 页脚更新检测由浏览器直连 api.github.com，与后端代理路径不一致&quot;">​</a></h2><ul><li><code>vite-frontend/src/components/version-footer.tsx:58</code> → <code>src/utils/version-update.ts:175</code>：浏览器 <code>fetch(&quot;https://api.github.com/repos/.../releases?per_page=50&quot;)</code> 直连，无代理、无鉴权（60 次/小时/IP 限额），失败静默（badge 不显示）</li><li>同一台机器上配置页的后端检查走代理（见下&quot;已验证&quot;），两条路径结果可不一致：页脚无红标 ≠ 无更新。分级 P3。</li></ul><h2 id="p3-4-代理地址归一化的小缺口" tabindex="-1">P3-4 代理地址归一化的小缺口 <a class="header-anchor" href="#p3-4-代理地址归一化的小缺口" aria-label="Permalink to &quot;P3-4 代理地址归一化的小缺口&quot;">​</a></h2><ul><li><code>upgrade.go</code> getGithubProxyConfig：TrimSpace、缺协议头补 <code>https://</code>、TrimSuffix 去<strong>一个</strong>尾斜杠。地址带多个尾斜杠（如 <code>https://ghfast.top//</code>）会拼出 <code>https://ghfast.top//https://github.com/...</code> 双斜杠路径，多数镜像可容忍但不保证；保存时前端对该字段<strong>无任何格式校验</strong>（config.tsx handleSave 仅对隧道质量间隔做校验），填错只能在下载失败时暴露且报错经 P2-3 的 Toast 难以看全。分级 P3。</li><li>附带说明（非缺陷）：该代理只加速 GitHub HTTP 下载（release 文件 + API），面板自升级后段的 GHCR 镜像 <code>docker compose pull</code> 不经此代理；面板机连不上 ghcr.io 时升级会在 helper 阶段失败，与加速设置无关，UI 对此无任何提示。</li></ul><h2 id="p3-5-死代码-buildgithubdownloadurl-无调用方" tabindex="-1">P3-5 死代码：buildGithubDownloadURL 无调用方 <a class="header-anchor" href="#p3-5-死代码-buildgithubdownloadurl-无调用方" aria-label="Permalink to &quot;P3-5 死代码：buildGithubDownloadURL 无调用方&quot;">​</a></h2><ul><li><code>go-backend/internal/http/handler/upgrade.go:111</code> <code>buildGithubDownloadURL</code> 全仓无调用（面板自升级实际用 <code>system_upgrade.go:463</code> 的 <code>buildSystemUpgradeDownloadURL</code>）。不影响功能，易误导后续维护。分级 P3。</li></ul><hr><h2 id="已验证通过-契约对表" tabindex="-1">已验证通过（契约对表） <a class="header-anchor" href="#已验证通过-契约对表" aria-label="Permalink to &quot;已验证通过（契约对表）&quot;">​</a></h2>',23),e("table",{tabindex:"0"},[e("thead",null,[e("tr",null,[e("th",null,"前端调用"),e("th",null,"后端注册"),e("th",null,"请求"),e("th",null,"响应字段对表")])]),e("tbody",null,[e("tr",null,[e("td",null,[e("code",null,"getSystemUpgradeVersion"),o(" POST "),e("code",null,"/system/version"),o("（api/index.ts:323）")]),e("td",null,[o("handler.go:204 "),e("code",null,"systemVersion")]),e("td",null,"无体"),e("td",null,[o("currentVersion/latestVersion/hasUpdate/channel/capability{capable,reasons,deployDir,backendContainer} 与 "),e("code",null,"types.ts:540-547"),o(),e("strong",null,"逐字一致"),o("；后端额外字段 pendingMigrations/adminBootstrapRequired 前端未声明，无害")])]),e("tr",null,[e("td",null,[e("code",null,"checkSystemUpgrade"),o(" POST "),e("code",null,"/system/check-updates"),o("（api/index.ts:326）")]),e("td",null,[o("handler.go:205 "),e("code",null,"systemCheckUpdates")]),e("td",null,[e("code",null,"{channel}"),o(" ↔ "),e("code",null,"systemUpgradeRequest{version,channel}")]),e("td",null,[o("+releases[]{version,name,publishedAt,prerelease,channel} 与 "),e("code",null,"types.ts:211-217"),o(),e("strong",null,"一致")])]),e("tr",null,[e("td",null,[e("code",null,"runSystemUpgrade"),o(" POST "),e("code",null,"/system/upgrade"),o("（api/index.ts:331，超时 60s）")]),e("td",null,[o("handler.go:206 "),e("code",null,"systemUpgrade")]),e("td",null,[e("code",null,'{version:"",channel}')]),e("td",null,[o("SystemUpgradeRunApiData{version,channel,composeAsset,helperContainer,backendImageId,message} 与后端 systemUpgradeRunData "),e("strong",null,"一致")])]),e("tr",null,[e("td",null,[e("code",null,"upgradeNode"),o(" POST "),e("code",null,"/node/upgrade"),o("（超时 5min ↔ 后端 SendCommand upgradeTimeout=5min，upgrade.go:31）")]),e("td",null,"—"),e("td",{"id,version,channel":""}),e("td",null,[o("1.0.10 新增的 proxyUrl 是面板→agent 内部下发，前端不感知，"),e("strong",null,"正常")])])])],-1),a('<ul><li><strong>当前版本来源（配置页）</strong>：后端 <code>currentPanelVersion()</code> 读 FLUX_VERSION 环境变量（system_upgrade.go:162），compose 以 <code>${FLUX_VERSION:-dev}</code> 注入（docker-compose-v4.yml:19），升级时由 updateEnvVersion 改写 .env——<strong>权威且与实际运行版本一致</strong>，与页脚的前端常量是两套来源（见 P2-1/P3-3 的不一致风险）。</li><li><strong>代理消费点全核对</strong>（键名均为 <code>github_proxy_enabled</code>/<code>github_proxy_url</code>，与前端字段 config.tsx:223/229 <strong>一致</strong>）：面板检查更新 <code>fetchSystemUpgradeReleases</code>（system_upgrade.go:479 前缀拼接）、面板下载资产 <code>buildSystemUpgradeDownloadURL</code>（:463）、节点安装命令（mutations.go:709）、内核下载（kernel.go:1231）、节点升级下发 proxyUrl（upgrade.go nodeUpgrade/nodeBatchUpgrade，1.0.10）。用户值 <code>https://ghfast.top</code>（有协议头、无尾斜杠）归一化后即 <code>&lt;proxy&gt;/https://github.com/...</code> 形式，可直接生效。</li><li><strong>O9-006 降级警告复核</strong>：config.tsx:1966-1985 在位且逻辑正确（compareVersions(选定, 当前) &lt; 0 时显示）；后端 O9-001 同步拒绝降级，前后端双保险。注意警告不禁用确认按钮，最终靠后端拒绝 + Toast 报错（受 P2-3 影响可读性）——可接受。</li><li><strong>防重复</strong>：确认按钮执行中 disabled、弹窗执行中不可关闭（config.tsx:1949-1953、2004-2012），后端 TryLock 兜底。</li><li><strong>渠道</strong>：前端 <code>getUpdateReleaseChannel()</code> 写死 stable（version-update.ts:47-48，注释明示本 fork 只发稳定版），后端 systemVersion 同样写死 stable，check-updates 按请求渠道过滤——三方一致，无 dev 渠道误导入口（弹窗文案里&quot;已选择正确的更新通道&quot;一句与无渠道选择器的现状略有出入，纯文案，归 P3-1 附带）。</li><li><strong>前端构建</strong>：<code>npx tsc --noEmit</code> <strong>通过</strong>（exit 0，无输出）。</li></ul><h2 id="未验证" tabindex="-1">未验证 <a class="header-anchor" href="#未验证" aria-label="Permalink to &quot;未验证&quot;">​</a></h2><ul><li>ghfast.top 对 <code>api.github.com</code> 路径与 release 资产的实际代理可用性（沙箱网络无法代表性验证）：建议用户在面板点一次「检查更新」——能列出版本列表即 API 代理通，能完成一次面板升级即资产代理通。</li><li>WebView 场景为代码推断（isWebViewFunc 分支），无真机 App 验证。</li></ul><h2 id="给用户的操作路径结论" tabindex="-1">给用户的操作路径结论 <a class="header-anchor" href="#给用户的操作路径结论" aria-label="Permalink to &quot;给用户的操作路径结论&quot;">​</a></h2><p>普通浏览器下：系统设置 → 面板自升级 →（当前/最新版本由后端给出，可信）→ 检查更新 → 选版本（或留空）→ 立即升级 → 确认 → 等约 1 分钟刷新，<strong>整条路径可走通</strong>；两个注意点：升级报错请第一时间截图（2 秒就消失，见 P2-3）；App 内嵌页面的左下角红标不要信（见 P2-1），以配置页显示的后端版本为准。</p>',5)])])}const b=l(n,[["render",s]]);export{m as __pageData,b as default};
